				<div class="elementor-widget-container">
									<ul><li><span>Bean</span></li><li><span>Nhân viên pha chế (barista)</span></li></ul>								</div>
				</div>
				<div class="elementor-element elementor-element-9898afa elementor-widget elementor-widget-heading" data-id="9898afa" data-element_type="widget" data-widget_type="heading.default">
				<div class="elementor-widget-container">
					<div class="elementor-heading-title elementor-size-default">Quy trình</div>				</div>
				</div>
				<div class="elementor-element elementor-element-ea0cdbc elementor-widget elementor-widget-text-editor" data-id="ea0cdbc" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
									<ul>
<li><span>Nhận yêu câu</span></li>
<li><span>Chấp nhận thanh toán</span></li>
<li><span>Xay đậu</span></li>
